  const playApplause=(force=false)=>{try{const prefs=JSON.parse(localStorage.getItem('ezgili-classroom-fun')||'{}');const mode=prefs.celebrationSound||'applause';if(mode==='silent'&&!force)return;const context=new window.AudioContext();if(mode==='gentle'&&!force){[523.25,659.25,783.99].forEach((frequency,index)=>{const oscillator=context.createOscillator(),gain=context.createGain(),at=context.currentTime+index*.16;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.001,at);gain.gain.exponentialRampToValueAtTime(.12,at+.04);gain.gain.exponentialRampToValueAtTime(.001,at+.42);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(at);oscillator.stop(at+.45);});window.setTimeout(()=>{void context.close()},1300);return;}const master=context.createGain();master.gain.value=.38;master.connect(context.destination);const start=context.currentTime;for(let i=0;i<52;i++){const duration=.07+Math.random()*.09,length=Math.ceil(context.sampleRate*duration),buffer=context.createBuffer(1,length,context.sampleRate),samples=buffer.getChannelData(0);for(let j=0;j<length;j++)samples[j]=(Math.random()*2-1)*(1-j/length);const source=context.createBufferSource(),filter=context.createBiquadFilter(),gain=context.createGain(),at=start+.04+Math.random()*1.55;source.buffer=buffer;filter.type='bandpass';filter.frequency.value=850+Math.random()*1250;filter.Q.value=.65;gain.gain.setValueAtTime(.001,at);gain.gain.exponentialRampToValueAtTime(.14+Math.random()*.16,at+.008);gain.gain.exponentialRampToValueAtTime(.001,at+duration);source.connect(filter);filter.connect(gain);gain.connect(master);source.start(at);source.stop(at+duration);}window.setTimeout(()=>{void context.close()},2500);}catch{}}
