      {tab==='Reward draw'&&<div className="page-wrap alternate"><p className="eyebrow">A MOMENT TO CELEBRATE</p><h1>Let’s make someone’s <em>day!</em></h1><p className="subhead">A little surprise for a whole lot of effort.</p><div className="draw-page-grid"><section className="draw-setup panel"><div className="panel-title"><div className="panel-icon coral"><Gift size={19}/></div><div><h2>Reward basket</h2><p>One student, one lovely surprise.</p></div></div><label className="field-label">Choose a classroom</label><select className="field-select" value={classroomId} onChange={e=>{setClassroomId(e.target.value);setDrawStudentId('')}}>{classrooms.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><label className="field-label">Who’s getting a treat?</label><select className="field-select" value={drawStudentId} onChange={e=>setDrawStudentId(e.target.value)}><option value="">Pick a student for me · equal chance</option>{students.map(s=><option key={String(s.id)} value={String(s.id)}>{displayStudentName(s.name)}</option>)}</select>{rollCall.taken?<label className="present-toggle"><input type="checkbox" checked={onlyPresent} onChange={e=>setOnlyPresent(e.target.checked)}/> <span>Only students who are here ({presentList.length} of {students.length})</span> <button type="button" className="text-link" onClick={()=>setRollOpen(true)}>Change</button></label>:<button type="button" className="roll-hint" onClick={()=>setRollOpen(true)}>📋 Take roll call so only students who are here can win</button>}<div className="fair-note"><ShieldCheck size={17}/><span>Every active student has an equal chance. Prizes are picked at random from your active collection.</span></div><button className="primary-btn draw-now" disabled={spinning} onClick={draw}>{spinning?<><span className="spinner"/> Shaking the basket…</>:<><Sparkles size={17}/> Draw a reward</>}</button><p className="small-center">Your draw is saved to the student’s reward history.</p></section><section className="basket-panel"><div className={`basket-scene ${spinning?'shake':''}`}><div className="scene-star star-a">✦</div><div className="scene-star star-b">✧</div><div className="basket-emoji">🧺</div><div className="scene-prize p-a">⭐</div><div className="scene-prize p-b">🎨</div><div className="scene-prize p-c">📚</div></div><div className="basket-caption"><strong>{spinning?'A little anticipation…':'The surprise basket'}</strong><span>{prizes.length} lovely things inside · All prizes have equal odds</span></div></section></div><section className="recent-panel panel"><div className="section-heading compact"><div><h2>Recent celebrations</h2><p>Little moments worth remembering.</p></div><div className="recent-tools"><div className="seg" role="group" aria-label="How much of the list to show">{([['full','All'],['half','Half'],['closed','Hide']] as const).map(([v,label])=><button key={v} type="button" className={rewardView===v?'on':''} aria-pressed={rewardView===v} onClick={()=>setRewardView(v)}>{label}</button>)}</div><button className="text-link" onClick={()=>navigateTab('Reports')}>See reports <ArrowRight size={15}/></button></div></div>{rewardView==='closed'?<p className="recent-closed">List hidden · {draws.length} {draws.length===1?'celebration':'celebrations'}. Tap “All” to show them.</p>:draws.length?<ul className="reward-rows">{draws.slice(0,rewardView==='half'?4:8).map((d,i)=><li className="reward-row" key={d.id??i}><span className="history-avatar">{d.avatar}</span><span className="reward-who"><strong>{displayStudentName(d.name)}</strong><small>🎁 {d.prize}</small></span><span className="history-time">{d.at}</span>{d.id&&<button type="button" className={`book-pill${d.bookReturned?' on':''}`} aria-pressed={Boolean(d.bookReturned)} onClick={()=>toggleBookReturned(d.id,!d.bookReturned)}>{d.bookReturned?'✅ Book returned':'📕 Book out'}</button>}</li>)}</ul>:<div className="empty-state"><div>🎁</div><strong>Your next happy memory starts here.</strong><span>Completed reward draws will show up here.</span></div>}</section></div>}
      {tab==='Classrooms'&&<div className="page-wrap classrooms-page"><div className="classes-head"><div><h1>Your classrooms</h1><p>{classroomCards.length} {classroomCards.length===1?'classroom':'classrooms'} · {(initialData.students as Array<{id:string}>).length} students</p></div><button className="primary-btn" onClick={()=>{setDraft('');setModal('newClass')}}><Plus size={16}/> New classroom</button></div><div className="classes-grid">{classroomCards.map(c=>{const kids=(initialData.students as Array<{classroom_id:string;avatar_key:string}>).filter(s=>s.classroom_id===c.id);return <article className="class-card" key={c.id}><div className="class-card-top"><span className="class-emoji" aria-hidden="true">{c.emoji}</span><div className="class-title"><h3>{c.name}</h3><p>{c.room}</p></div><button aria-label={`Archive ${c.name}`} title="Archive classroom" className="icon-btn class-archive" onClick={()=>archiveClass(c.id)}><Archive size={17}/></button></div><div className="class-faces" aria-hidden="true">{kids.slice(0,7).map((s,i)=><span key={i}>{avatarMap[String(s.avatar_key)]||'🙂'}</span>)}{kids.length>7&&<b>+{kids.length-7}</b>}{!kids.length&&<small>No students yet</small>}</div><div className="class-actions"><button type="button" className="primary-btn" onClick={()=>{setClassroomId(c.id);setClassroom(c.name);navigateTab('Today')}}>Open classroom <ChevronRight size={15}/></button><button type="button" className="outline-btn" onClick={()=>{setClassroomId(c.id);setClassroom(c.name);navigateTab('Today');setDraft('');setPhotoNames([]);setPhotoError('');setModal('addStudent')}}><Plus size={15}/> Add students</button></div></article>})}</div></div>}
      {tab==='Reports'&&<div className="page-wrap alternate"><p className="eyebrow">CELEBRATE EVERY STEP</p><h1>Look how far they’ve <em>come.</em></h1><p className="subhead">A little progress, all in one place.</p><div className="report-toolbar"><div className="group-picker"><Users size={16}/><select value={classroomId} onChange={e=>setClassroomId(e.target.value)}>{classrooms.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><ChevronDown size={15}/></div><div className="segmented">{['This week','This month'].map(p=><button key={p} className={period===p?'selected':''} onClick={()=>setPeriod(p)}>{p}</button>)}</div></div><div className="report-summary"><div className="report-hero"><span>YOUR CLASSROOM’S GLOW</span><strong>{(reportData?.rows.reduce((sum,row)=>sum+Number(row.total||0),0)??0)}</strong><small>points earned {period==='This week'?'this week':'this month'} ✨</small><div className="report-doodles">✿ &nbsp;✦&nbsp; ✿</div></div><div className="report-stat"><span>TOP CRITERION</span><strong>{criteria[0]}</strong><small>{reportData?.rows.reduce((sum,row)=>sum+Number(row.homework_complete||0),0)??0} points earned</small></div><div className="report-stat"><span>CLASSROOM STREAK</span><strong>5 <small>days</small></strong><small>Look at you, Sunflowers!</small></div></div><section className="report-table panel"><div className="section-heading compact"><div><h2>Student progress</h2><p>Totals for {reportData?`${reportData.from} – ${reportData.to}`:'Loading date range…'}</p></div><button className="outline-btn" onClick={()=>notify('Report ready to print')}><Activity size={15}/> Print report</button></div><div className="table-scroll"><table><thead><tr><th>STUDENT</th>{['Homework','Participation','Speaking','Project','Ready','Rules','Book return'].map((label,i)=><th key={i}>{label}</th>)}<th>TOTAL</th></tr></thead><tbody>{reportData?.rows.map((row,i)=><tr key={String(row.id)}><td><span className="table-student"><i>{({fox:'🦊',bear:'🐻',panda:'🐼',lion:'🦁',frog:'🐸',tiger:'🐯',koala:'🐨',unicorn:'🦄',penguin:'🐧',octopus:'🐙'} as Record<string,string>)[String(row.avatar_key)]||'🙂'}</i><strong>{displayStudentName(String(row.display_name))}</strong></span></td>{['homework_complete','class_participation','speaking_effort','project_complete','class_readiness','speaking_day_rules','book_return'].map(key=><td key={key}>{Number(row[key]||0)}</td>)}<td><b>{Number(row.total||0)}</b></td></tr>)}</tbody><tfoot><tr><td>Class total</td>{['homework_complete','class_participation','speaking_effort','project_complete','class_readiness','speaking_day_rules','book_return'].map(key=><td key={key}>{reportData?.rows.reduce((sum,row)=>sum+Number(row[key]||0),0)??0}</td>)}<td>{(reportData?.rows.reduce((sum,row)=>sum+Number(row.total||0),0)??0)}</td></tr></tfoot></table></div></section><div className="report-note"><ShieldCheck size={16}/> Reports use your classroom’s local timezone. Days without a check-in count as zero points.</div></div>}
